Aqui está a solução completa e eficiente em C para o problema.

A ideia consiste em modelar o problema com um grafo estendido:
1. Para cada estação $u$, temos um nó base representando a estação "fora" de qualquer sistema de transporte.
2. Para cada sistema $t$ incidente em $u$, temos um estado $(u, t)$. Como a soma dos graus é no máximo $2M$, existem no máximo $2M$ pares $(u, t)$.
3. As transições são:
   - De $u$ para $(u, t)$ com custo $P_t$ (pagar a passagem e entrar no sistema $t$).
   - De $(u, t)$ para $u$ com custo 0 (sair do sistema).
   - De $(u, t)$ para $(v, t)$ com custo 0 para cada aresta $(u, v)$ do tipo $t$ (deslocamento gratuito dentro do mesmo sistema).
4. O menor caminho pode ser encontrado usando o algoritmo de Dijkstra com um heap binário.

```c
#include <stdio.h>
#include <stdlib.h>

#define INF 0x3f3f3f3f3f3f3f3fLL

typedef struct {
    int to;
    int weight;
    int next;
} Edge;

typedef struct {
    int u, v, t;
} InputEdge;

typedef struct {
    int u, t;
} Pair;

int compare_pairs(const void *a, const void *b) {
    Pair *pa = (Pair *)a;
    Pair *pb = (Pair *)b;
    if (pa->u != pb->u) return pa->u - pb->u;
    return pa->t - pb->t;
}

// Representação de nós e arestas do grafo para o Dijkstra
static int head[500005];
static Edge edges[2000005];
static int edge_cnt = 0;

void add_edge(int from, int to, int weight) {
    edges[++edge_cnt].to = to;
    edges[edge_cnt].weight = weight;
    edges[edge_cnt].next = head[from];
    head[from] = edge_cnt;
}

// Binary Search para encontrar o ID do par (u, t)
int get_state_id(Pair *arr, int size, int u, int t) {
    int low = 0, high = size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid].u == u && arr[mid].t == t) {
            return mid;
        }
        if (arr[mid].u < u || (arr[mid].u == u && arr[mid].t < t)) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

// Min-Heap para o Dijkstra
typedef struct {
    long long dist;
    int u;
} HeapNode;

static HeapNode heap[2000005];
static int heap_size = 0;

void heap_push(int u, long long dist) {
    heap[++heap_size] = (HeapNode){dist, u};
    int i = heap_size;
    while (i > 1 && heap[i].dist < heap[i / 2].dist) {
        HeapNode tmp = heap[i];
        heap[i] = heap[i / 2];
        heap[i / 2] = tmp;
        i /= 2;
    }
}

HeapNode heap_pop() {
    HeapNode top = heap[1];
    heap[1] = heap[heap_size--];
    int i = 1;
    while (2 * i <= heap_size) {
        int left = 2 * i;
        int right = 2 * i + 1;
        int smallest = i;
        if (heap[left].dist < heap[smallest].dist) smallest = left;
        if (right <= heap_size && heap[right].dist < heap[smallest].dist) smallest = right;
        if (smallest != i) {
            HeapNode tmp = heap[i];
            heap[i] = heap[smallest];
            heap[smallest] = tmp;
            i = smallest;
        } else {
            break;
        }
    }
    return top;
}

static long long dist[500005];
static int P[100005];
static InputEdge in_edges[100005];
static Pair pairs[200005];

int main() {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    for (int i = 1; i <= K; ++i) {
        scanf("%d", &P[i]);
    }

    int pair_count = 0;
    for (int i = 0; i < M; ++i) {
        scanf("%d %d %d", &in_edges[i].u, &in_edges[i].v, &in_edges[i].t);
        pairs[pair_count++] = (Pair){in_edges[i].u, in_edges[i].t};
        pairs[pair_count++] = (Pair){in_edges[i].v, in_edges[i].t};
    }

    int A, B;
    scanf("%d %d", &A, &B);

    // Ordenar e remover duplicatas dos pares (estação, tipo)
    qsort(pairs, pair_count, sizeof(Pair), compare_pairs);
    int unique_pairs = 0;
    for (int i = 0; i < pair_count; ++i) {
        if (i == 0 || pairs[i].u != pairs[i - 1].u || pairs[i].t != pairs[i - 1].t) {
            pairs[unique_pairs++] = pairs[i];
        }
    }

    // Identificadores de nós:
    // Estações normais: 1 até N
    // Estados (u, t): N + 1 + índice_do_par (0 a unique_pairs - 1)
    for (int i = 0; i < unique_pairs; ++i) {
        int u = pairs[i].u;
        int t = pairs[i].t;
        int state_node = N + 1 + i;

        // Entrar no sistema: de u para (u, t) com custo P[t]
        add_edge(u, state_node, P[t]);

        // Sair do sistema: de (u, t) para u com custo 0
        add_edge(state_node, u, 0);
    }

    // Arestas de locomoção dentro do mesmo sistema
    for (int i = 0; i < M; ++i) {
        int u = in_edges[i].u;
        int v = in_edges[i].v;
        int t = in_edges[i].t;

        int u_state = N + 1 + get_state_id(pairs, unique_pairs, u, t);
        int v_state = N + 1 + get_state_id(pairs, unique_pairs, v, t);

        add_edge(u_state, v_state, 0);
        add_edge(v_state, u_state, 0);
    }

    // Dijkstra
    int total_nodes = N + unique_pairs;
    for (int i = 1; i <= total_nodes; ++i) {
        dist[i] = INF;
    }

    dist[A] = 0;
    heap_push(A, 0);

    while (heap_size > 0) {
        HeapNode top = heap_pop();
        int u = top.u;
        long long d = top.dist;

        if (d > dist[u]) continue;
        if (u == B) break;

        for (int e = head[u]; e != 0; e = edges[e].next) {
            int v = edges[e].to;
            int w = edges[e].weight;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                heap_push(v, dist[v]);
            }
        }
    }

    if (dist[B] >= INF) {
        printf("-1\n");
    } else {
        printf("%lld\n", dist[B]);
    }

    return 0;
}
